mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM trip_items
    WHERE trip_id = #{tripId}
      AND item_id = #{itemId}
      AND visit_date = #{visitDate}
      AND deleted_at IS NULL
)

mapper.update:
UPDATE trip_items
SET deleted_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE trip_id = #{tripId}
  AND appointment_id = #{appointmentId}
  AND deleted_at IS NULL

UPDATE trip_items
SET deleted_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE trip_id = #{tripId}
  AND trip_item_id = #{tripItemId}
  AND deleted_at IS NULL
